CREATE OR REPLACE FUNCTION public.fusion_review_source(p_actor_id uuid, p_review_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE rv fusion_reviews; ver artifact_versions; r artifact_rounds;
BEGIN
